INSERT INTO coordinator_auth_link_authority_upgrade_checks VALUES ((NOT EXISTS (
 WITH RECURSIVE retained_refs(value) AS (
  SELECT ids.value FROM coordinator_auth_link_attempts legacy, json_each(json_array(legacy.coordinator_id, legacy.attempt_id, legacy.identity_id, legacy.group_id, legacy.device_id, legacy.controller_attestation_id, legacy.controller_review_receipt_id, legacy.link_id)) ids UNION SELECT ids.value FROM coordinator_auth_account_links legacy, json_each(json_array(legacy.coordinator_id, legacy.link_id, legacy.identity_id, legacy.attempt_id, legacy.controller_attestation_id)) ids UNION SELECT ids.value FROM coordinator_auth_link_audit_log legacy, json_each(json_array(legacy.coordinator_id, legacy.link_id, legacy.attempt_id, legacy.identity_id, legacy.group_id, legacy.device_id, legacy.controller_attestation_id)) ids),
 refs(value) AS (SELECT value FROM retained_refs WHERE value IS NOT NULL),
 characters(value, position, cp) AS (
 SELECT value, 1, unicode(substr(value, 1, 1)) FROM refs
 UNION ALL SELECT value, position + 1, unicode(substr(value, position + 1, 1)) FROM characters
 WHERE position < length(value) AND position < 256)
 SELECT value FROM characters GROUP BY value HAVING NOT (value IS NOT NULL AND typeof(value) = 'text' AND length(value) BETWEEN 1 AND 256 AND value = trim(value) AND instr(value, char(0)) = 0)
 OR sum(CASE WHEN cp > 65535 THEN 2 ELSE 1 END) > 256
 OR max((cp BETWEEN 0 AND 31) OR (cp BETWEEN 127 AND 159) OR (cp BETWEEN 173 AND 173) OR (cp BETWEEN 1536 AND 1541) OR (cp BETWEEN 1564 AND 1564) OR (cp BETWEEN 1757 AND 1757) OR (cp BETWEEN 1807 AND 1807) OR (cp BETWEEN 2192 AND 2193) OR (cp BETWEEN 2274 AND 2274) OR (cp BETWEEN 6158 AND 6158) OR (cp BETWEEN 8203 AND 8207) OR (cp BETWEEN 8234 AND 8238) OR (cp BETWEEN 8288 AND 8292) OR (cp BETWEEN 8294 AND 8303) OR (cp BETWEEN 55296 AND 57343) OR (cp BETWEEN 65279 AND 65279) OR (cp BETWEEN 65529 AND 65531) OR (cp BETWEEN 69821 AND 69821) OR (cp BETWEEN 69837 AND 69837) OR (cp BETWEEN 78896 AND 78911) OR (cp BETWEEN 113824 AND 113827) OR (cp BETWEEN 119155 AND 119162) OR (cp BETWEEN 917505 AND 917505) OR (cp BETWEEN 917536 AND 917631)
 OR (position IN (1, length(value)) AND cp IN (32,160,5760,8192,8193,8194,8195,8196,8197,8198,8199,8200,8201,8202,8232,8233,8239,8287,12288))) = 1)));
