 AND e.attempt_id = a.attempt_id AND e.identity_id = a.identity_id
 AND e.group_id = a.group_id AND e.device_id = a.device_id AND e.fingerprint = a.fingerprint
 AND e.controller_attestation_id = a.controller_attestation_id AND e.auth_config_revision = a.auth_config_revision AND e.action = 'link_created' AND e.created_at_ms = l.created_at_ms)
 OR (l.revoked_at_ms IS NOT NULL AND NOT EXISTS (SELECT 1 FROM coordinator_auth_link_audit_log e WHERE e.coordinator_id = a.coordinator_id AND e.link_id = a.link_id
 AND e.attempt_id = a.attempt_id AND e.identity_id = a.identity_id
 AND e.group_id = a.group_id AND e.device_id = a.device_id AND e.fingerprint = a.fingerprint
 AND e.controller_attestation_id = a.controller_attestation_id AND e.auth_config_revision = a.auth_config_revision AND e.action = 'link_revoked' AND e.created_at_ms = l.revoked_at_ms)))));
INSERT INTO coordinator_auth_link_authority_upgrade_checks VALUES ((NOT EXISTS (SELECT 1 FROM coordinator_auth_link_audit_log e WHERE NOT EXISTS (
 SELECT 1 FROM coordinator_auth_account_links l JOIN coordinator_auth_link_attempts a ON a.coordinator_id = l.coordinator_id AND a.attempt_id = l.attempt_id
 AND a.link_id = l.link_id AND a.identity_id = l.identity_id AND a.issuer = l.issuer
 AND a.account_subject = l.subject AND a.controller_attestation_id = l.controller_attestation_id
 AND a.auth_config_revision = l.auth_config_revision AND a.finalized_at_ms = l.created_at_ms
 AND a.state IN ('finalized','session_redeemed') WHERE e.coordinator_id = a.coordinator_id AND e.link_id = a.link_id
 AND e.attempt_id = a.attempt_id AND e.identity_id = a.identity_id
 AND e.group_id = a.group_id AND e.device_id = a.device_id AND e.fingerprint = a.fingerprint
 AND e.controller_attestation_id = a.controller_attestation_id AND e.auth_config_revision = a.auth_config_revision
 AND ((e.action = 'link_created' AND e.created_at_ms = l.created_at_ms)
