INSERT INTO coordinator_auth_link_authority_upgrade_checks VALUES ((NOT EXISTS (SELECT rowid, coordinator_id, attempt_id, identity_id, group_id, device_id, public_key, fingerprint, controller_attestation_id, controller_review_receipt_id, controller_revision, issuer, auth_config_revision, runtime_verifier_hash, loopback_redirect, state, browser_transaction_hash, account_subject, completion_secret_hash, link_id, failure_reason, created_at_ms, expires_at_ms, claimed_at_ms, oidc_verified_at_ms, confirmed_at_ms, finalized_at_ms, failed_at_ms, browser_start_hash FROM coordinator_auth_link_attempts_authority_upgrade EXCEPT SELECT rowid, coordinator_id, attempt_id, identity_id, group_id, device_id, public_key, fingerprint, controller_attestation_id, controller_review_receipt_id, controller_revision, issuer, auth_config_revision, runtime_verifier_hash, loopback_redirect, state, browser_transaction_hash, account_subject, completion_secret_hash, link_id, failure_reason, created_at_ms, expires_at_ms, claimed_at_ms, oidc_verified_at_ms, confirmed_at_ms, finalized_at_ms, failed_at_ms, browser_start_hash FROM coordinator_auth_link_attempts)));
